inputs.value:
{
  "authority": {
    "Load the Governing Instruction": {
      "primary": "Current account-level custom instruction",
      "authoritativeFile": "/AGENTS.md",
      "fileLocation": "ChatGPT Library root",
      "mirror": {
        "provider": "Google Drive",
        "file_id": "1mOA-U6vw6luQslJxvWffPghl9TTNw3hE",
        "url": "https://drive.google.com/file/d/1mOA-U6vw6luQslJxvWffPghl9TTNw3hE/view?usp=drivesdk"
      }
    }
  },
  "capture": {
    "Load the Governing Instruction": {
      "inputs": {
        "governingInstructionFileId": {
          "definition": "The current backing file ID returned by live retrieval of the governing instruction. Read the complete current instruction, capture this ID from its retrieval metadata, and return the exact value. Return null only when unavailable; never infer or reuse an old ID.",
          "type": [
            "string",
            "null"
          ]
        },
        "governingInstructionLibraryFileId": {
          "definition": "The persistent Library record ID returned by the same live retrieval of the governing instruction. Capture and return its exact value, independently of the backing file ID. Return null only when unavailable; never infer or substitute a different identifier.",
          "type": [
            "string",
            "null"
          ]
        },
        "instructionScope": {
          "definition": "The prompts or contexts in which the governing instruction applies. This describes instruction applicability, independently of the scope of a requested change.",
          "type": "string"
        }
      },
      "questions": [
        {
          "question": "What is the ${governingInstructionFileId.definition}?",
          "return": "${governingInstructionFileId}"
        },
        {
          "question": "What is the ${governingInstructionLibraryFileId.definition}?",
          "return": "${governingInstructionLibraryFileId}"
        },
        {
          "question": "What is the ${instructionScope.definition}?",
          "return": "${instructionScope}"
        }
      ]
    }
  }
}
